import path from 'node:path'
import { drizzle } from 'drizzle-orm/postgres-js'
import { migrate } from 'drizzle-orm/postgres-js/migrator'
import postgres from 'postgres'

/** Advisory lock id for migrations ("ddp-migrate"); distinct from the content-store lock. */
const MIGRATE_LOCK = 0x0dd9_0a1e

/**
 * Apply the SQL migrations in drizzle/ (generated by `npm run db:generate`).
 * Runs at server start (src/instrumentation.ts) and before the test suite.
 * Uses its own single connection (so the session lock below covers every
 * statement) and closes it when done. Two processes starting at once take turns.
 */
export async function runMigrations(url = process.env.DATABASE_URL): Promise<void> {
  if (!url) throw new Error('DATABASE_URL is not set')
  const folder = path.resolve(/*turbopackIgnore: true*/ process.env.MIGRATIONS_DIR || path.join(process.cwd(), 'drizzle'))
  const sql = postgres(url, { max: 1, onnotice: () => {} })
  try {
    await sql`select pg_advisory_lock(${MIGRATE_LOCK})`
    try {
      await migrate(drizzle(sql), { migrationsFolder: folder })
    } finally {
      await sql`select pg_advisory_unlock(${MIGRATE_LOCK})`
    }
  } finally {
    await sql.end({ timeout: 5 })
  }
}
